      _hashTypedDataV4(keccak256(abi.encode(DELEGATION_TYPEHASH, _signer, _delegatee, _useNonce(_signer), _expiry))),
      _signature
    );

    if (!_isSignatureValid) {
      revert DelegateSignatureIsInvalid();
    }
    _delegate(_signer, _delegatee);
  }
}

